<?php batasi_akses_role(['admin','petugas']);
$tahun=$_GET['tahun']??date('Y');
$q=mysqli_query($koneksi,"SELECT MONTH(tanggalpenanganan) as bln, COUNT(*) as jml, SUM(CASE WHEN statuspasien='sembuh' THEN 1 ELSE 0 END) as sembuh, SUM(CASE WHEN statuspasien='rujuk' THEN 1 ELSE 0 END) as rujuk FROM penanganan WHERE YEAR(tanggalpenanganan)='$tahun' GROUP BY MONTH(tanggalpenanganan) ORDER BY bln ASC");
$detail=mysqli_query($koneksi,"SELECT p.*, s.namasiswa, g.namaguru FROM penanganan p LEFT JOIN siswa s ON p.idsiswa=s.idsiswa LEFT JOIN guru g ON p.idguru=g.idguru WHERE YEAR(p.tanggalpenanganan)='$tahun' ORDER BY p.tanggalpenanganan DESC");
?>
<div class="content-header"><div class="container-fluid"><div class="row mb-2"><div class="col-sm-6"><h1 class="m-0 text-success font-weight-bold"><i class="fas fa-chart-bar mr-1"></i> Laporan Tahunan <?= $tahun ?></h1></div><div class="col-sm-6 text-right"><form method="GET" class="form-inline float-right"><input type="hidden" name="halaman" value="laporantahunan"><select name="tahun" class="form-control form-control-sm mr-2"><?php for($t=date('Y');$t>=2023;$t--) echo "<option value='$t' ".($tahun==$t?'selected':'').">$t</option>"; ?></select><button class="btn btn-success btn-sm">Tampilkan</button> <a href="index.php?halaman=cetaklaporantahunan&tahun=<?= $tahun ?>" target="_blank" class="btn btn-danger btn-sm ml-1"><i class="fas fa-print"></i> Cetak</a></form></div></div></div></div>
<div class="content"><div class="container-fluid"><div class="row"><div class="col-md-4"><div class="card card-success card-outline shadow-sm"><div class="card-header bg-light font-weight-bold">Rekap Per Bulan</div><div class="card-body p-0"><table class="table table-sm mb-0"><thead class="bg-light"><tr><th>Bulan</th><th>Total</th><th>Sembuh</th><th>Rujuk</th></tr></thead><tbody><?php while($r=mysqli_fetch_assoc($q)): ?><tr><td><?= date('F',mktime(0,0,0,$r['bln'],1)) ?></td><td><b><?= $r['jml'] ?></b></td><td><?= $r['sembuh'] ?></td><td><?= $r['rujuk'] ?></td></tr><?php endwhile; ?></tbody></table></div></div></div><div class="col-md-8"><div class="card card-success card-outline shadow-sm"><div class="card-body p-0 table-responsive"><table class="table table-bordered mb-0"><thead class="bg-light"><tr><th>Tgl</th><th>Pasien</th><th>Keluhan</th><th>Status</th></tr></thead><tbody><?php while($d=mysqli_fetch_assoc($detail)): ?><tr><td><small><?= $d['tanggalpenanganan'] ?></small></td><td><?= $d['namasiswa']?:$d['namaguru'] ?></td><td><small><?= $d['keluhan'] ?></small></td><td><?= $d['statuspasien'] ?></td></tr><?php endwhile; ?></tbody></table></div></div></div></div></div></div>